// Pseudo-code for resetting a list of class mocks

// FUNCTION: reset
// INPUT: classMocks - a variable-length argument of Class types representing the mocks to reset
FUNCTION reset(classMocks: Class<?>...) 
    // FOR each class type in the provided classMocks
    FOR each type IN classMocks DO
        // Get the invocation handler for static method control
        invocationHandler = MockRepository.getStaticMethodInvocationControl(type)

        // IF invocation handler is not null
        IF invocationHandler IS NOT NULL THEN
            // Reset the invocation handler
            invocationHandler.reset()
        END IF

        // Get the invocation control for new instance control
        newInvocationControl = MockRepository.getNewInstanceControl(type)

        // IF new invocation control is not null
        IF newInvocationControl IS NOT NULL THEN
            // TRY to reset the new invocation control
            TRY
                newInvocationControl.reset()
            // CATCH any assertion error
            CATCH AssertionError e DO
                // Throw a specific assertion error for new substitution failure
                NewInvocationControlAssertionError.throwAssertionErrorForNewSubstitutionFailure(e, type)
            END TRY
        END IF
    END FOR
END FUNCTION
