```
// Creates a new timer function using the given template
// This method initializes the default timers.

// Define input parameter
INPUT: timerTemplate - A supplier that provides a Timer.Builder instance

// Define output
OUTPUT: A function that takes a Code and returns a Timer

FUNCTION asTimerFunction(timerTemplate: Supplier<Timer.Builder>) RETURNS Function<Code, Timer>:
    // Initialize a cache to store Timer instances associated with Code
    DECLARE cache AS EnumMap<Code, Timer>

    // Define a creator function that creates a Timer for a given Code
    DECLARE creator AS Function<Code, Timer>
    creator = code -> 
        // Get a new Timer.Builder from the timerTemplate
        timerTemplate.get()
            // Tag the Timer with the status code
            .tag(TAG_STATUS_CODE, code.name())
            // Register the Timer in the registry
            .register(this.registry)

    // Define a cache resolver to return Timer from cache or create if absent
    DECLARE cacheResolver AS Function<Code, Timer>
    cacheResolver = code -> 
        // Compute and return Timer from cache or create a new one using creator
        cache.computeIfAbsent(code, creator)

    // Eagerly initialize Timers for predefined Codes
    FOR each code IN this.eagerInitializedCodes:
        cacheResolver.apply(code)

    // Return the cache resolver function
    RETURN cacheResolver
