FUNCTION registerLowLevelResultListener(listener: LowLevelResultListener<R>) -> LowLevelResultListener<R>
    // Store the previously registered listener
    prev <- this.listener

    // Check if the provided listener is null
    IF listener IS NULL THEN
        // Set the listener to a "none" listener
        this.listener <- LowLevelResultListener.none()
    ELSE
        // Register the provided listener
        this.listener <- listener
    ENDIF

    // Return the previously registered listener, which is never null
    RETURN prev
