// Function to add a value to a list of values in the map
FUNCTION addToValueList(map, key, value) RETURNS List<V>
    // Retrieve the list associated with the given key from the map
    valueList = map.get(key)

    // Check if the list does not exist for the key
    IF valueList IS NULL THEN
        // Create a new list since no existing list was found
        valueList = new List<V>()
        // Store the newly created list in the map with the given key
        map.put(key, valueList)
    ENDIF

    // Add the specified value to the list
    valueList.add(value)

    // Return the updated list of values
    RETURN valueList
END FUNCTION
```

