```
// Function to copy data from an input stream to an output stream
FUNCTION copyWriterCount(inputstream in, outpustream out) RETURNS integer
    // Initialize total bytes copied
    INTEGER totalBytesCopied = 0
    // Create a buffer to hold data chunks
    CHARACTER_ARRAY buffer[10240]
    // Read data from input stream into buffer
    INTEGER bytesRead = in.read(buffer)

    // Loop until no more data is read
    WHILE bytesRead >= 0 DO
        IF bytesRead > 0 THEN
            // Write the read data to output stream
            out.write(buffer, 0, bytesRead)
            // Update the total bytes copied
            totalBytesCopied += bytesRead
        ENDIF
        // Read the next chunk of data
        bytesRead = in.read(buffer)
    ENDWHILE

    // Return the total number of bytes copied
    RETURN totalBytesCopied
ENDFUNCTION
```

