// Function to retrieve the generated primary key from a prepared insert statement
FUNCTION getGeneratedKey(statement: PreparedStatement) RETURNS int
    // Initialize variable for the primary key
    DECLARE id AS int = 0
    // Declare variable for result set
    DECLARE rs AS ResultSet

    // Attempt to retrieve generated keys
    TRY
        // Get the generated keys from the prepared statement
        rs = statement.getGeneratedKeys()

        // Check if result set has keys
        IF NOT rs.next() THEN
            // Throw exception if no keys are found
            THROW DatabaseException("Unable to get primary key for inserted row")
        ENDIF

        // Retrieve the primary key from the result set
        id = rs.getInt(1)
    CATCH SQLException AS ex
        // Throw exception in case of SQL error
        THROW DatabaseException("Unable to get primary key for inserted row")
    FINALLY
        // Close the result set
        closeResultSet(rs)
    ENDTRY

    // Return the generated primary key
    RETURN id
END FUNCTION
