code:
public static void echoFrame(final WebSocketChannel channel, final StreamSourceFrameChannel ws) throws IOException {

        final WebSocketFrameType type;
        switch (ws.getType()) {
            case PONG:
                // pong frames must be discarded
                ws.close();
                return;
            case PING:
                // if a ping is send the autobahn testsuite expects a PONG when echo back
                type = WebSocketFrameType.PONG;
                break;
            default:
                type = ws.getType();
                break;
        }
        final StreamSinkFrameChannel sink = channel.send(type);
        sink.setRsv(ws.getRsv());
        initiateTransfer(ws, sink, new ChannelListener<StreamSourceFrameChannel>() {
                    @Override
                    public void handleEvent(StreamSourceFrameChannel streamSourceFrameChannel) {
                        IoUtils.safeClose(streamSourceFrameChannel);
                    }
                }, new ChannelListener<StreamSinkFrameChannel>() {
                    @Override
                    public void handleEvent(StreamSinkFrameChannel streamSinkFrameChannel) {
                        try {
                            streamSinkFrameChannel.shutdownWrites();
                        } catch (IOException e) {
                            UndertowLogger.REQUEST_IO_LOGGER.ioException(e);
                            IoUtils.safeClose(streamSinkFrameChannel, channel);
                            return;
                        }
                        try {
                            if (!streamSinkFrameChannel.flush()) {
                                streamSinkFrameChannel.getWriteSetter().set(ChannelListeners.flushingChannelListener(
                                        new ChannelListener<StreamSinkFrameChannel>() {
                                            @Override
                                            public void handleEvent(StreamSinkFrameChannel streamSinkFrameChannel) {
                                                streamSinkFrameChannel.getWriteSetter().set(null);
                                                IoUtils.safeClose(streamSinkFrameChannel);
                                                if (type == WebSocketFrameType.CLOSE) {
                                                    IoUtils.safeClose(channel);
                                                }
                                            }
                                        }, new ChannelExceptionHandler<StreamSinkFrameChannel>() {
                                            @Override
                                            public void handleException(StreamSinkFrameChannel streamSinkFrameChannel, IOException e) {

                                                UndertowLogger.REQUEST_IO_LOGGER.ioException(e);
                                                IoUtils.safeClose(streamSinkFrameChannel, channel);

                                            }
                                        }
                                ));
                                streamSinkFrameChannel.resumeWrites();
                            } else {
                                if (type == WebSocketFrameType.CLOSE) {
                                    IoUtils.safeClose(channel);
                                }
                                streamSinkFrameChannel.getWriteSetter().set(null);
                                IoUtils.safeClose(streamSinkFrameChannel);
                            }
                        } catch (IOException e) {
                            UndertowLogger.REQUEST_IO_LOGGER.ioException(e);
                            IoUtils.safeClose(streamSinkFrameChannel, channel);

                        }
                    }
                }, new ChannelExceptionHandler<StreamSourceFrameChannel>() {
                    @Override
                    public void handleException(StreamSourceFrameChannel streamSourceFrameChannel, IOException e) {
                        UndertowLogger.REQUEST_IO_LOGGER.ioException(e);
                        IoUtils.safeClose(streamSourceFrameChannel, channel);
                    }
                }, new ChannelExceptionHandler<StreamSinkFrameChannel>() {
                    @Override
                    public void handleException(StreamSinkFrameChannel streamSinkFrameChannel, IOException e) {
                        UndertowLogger.REQUEST_IO_LOGGER.ioException(e);
                        IoUtils.safeClose(streamSinkFrameChannel, channel);
                    }
                }, channel.getBufferPool()
        );

    }

pseudo_code:
```plaintext
// Function to echo back the frame to the sender
FUNCTION echoFrame(channel: WebSocketChannel, ws: StreamSourceFrameChannel) RETURNS VOID
    // Define the type of WebSocket frame
    DECLARE type AS WebSocketFrameType

    // Determine the type of incoming WebSocket frame
    SWITCH ws.getType() 
        CASE PONG:
            // Discard pong frames
            ws.close()
            RETURN
        CASE PING:
            // Prepare to send a PONG frame in response to a PING
            type = WebSocketFrameType.PONG
            BREAK
        DEFAULT:
            // Use the same type for other frames
            type = ws.getType()
            BREAK
    END SWITCH

    // Prepare to send the frame of the determined type
    DECLARE sink AS StreamSinkFrameChannel
    sink = channel.send(type)
    sink.setRsv(ws.getRsv())

    // Initiate the transfer of the frame
    initiateTransfer(ws, sink, 
        // Listener for source frame channel events
        FUNCTION(streamSourceFrameChannel)
            // Safely close the source frame channel
            IoUtils.safeClose(streamSourceFrameChannel)
        END FUNCTION,
        // Listener for sink frame channel events
        FUNCTION(streamSinkFrameChannel)
            TRY
                // Shutdown writes on the sink channel
                streamSinkFrameChannel.shutdownWrites()
            CATCH IOException AS e
                // Log IOException and safely close channels
                UndertowLogger.REQUEST_IO_LOGGER.ioException(e)
                IoUtils.safeClose(streamSinkFrameChannel, channel)
                RETURN
            END TRY

            TRY
                // Attempt to flush the sink channel
                IF NOT streamSinkFrameChannel.flush() THEN
                    // Set flushing listener for the sink channel
                    streamSinkFrameChannel.getWriteSetter().set(ChannelListeners.flushingChannelListener(
                        FUNCTION(flushingStreamSinkFrameChannel)
                            // Clear the write setter and close the channel
                            flushingStreamSinkFrameChannel.getWriteSetter().set(null)
                            IoUtils.safeClose(flushingStreamSinkFrameChannel)
                            // Close the main channel if the frame type is CLOSE
                            IF type == WebSocketFrameType.CLOSE THEN
                                IoUtils.safeClose(channel)
                            END IF
                        END FUNCTION,
                        // Exception handler for flushing
                        FUNCTION(flushingStreamSinkFrameChannel, e: IOException)
                            // Log IOException and safely close channels
                            UndertowLogger.REQUEST_IO_LOGGER.ioException(e)
                            IoUtils.safeClose(flushingStreamSinkFrameChannel, channel)
                        END FUNCTION
                    ))
                    // Resume writes on the sink channel
                    streamSinkFrameChannel.resumeWrites()
                ELSE
                    // If flush is successful, check if the frame type is CLOSE
                    IF type == WebSocketFrameType.CLOSE THEN
                        IoUtils.safeClose(channel)
                    END IF
                    // Clear the write setter and close the sink channel
                    streamSinkFrameChannel.getWriteSetter().set(null)
                    IoUtils.safeClose(streamSinkFrameChannel)
                END IF
            CATCH IOException AS e
                // Log IOException and safely close channels
                UndertowLogger.REQUEST_IO_LOGGER.ioException(e)
                IoUtils.safeClose(streamSinkFrameChannel, channel)
            END TRY
        END FUNCTION,
        // Exception handler for source frame channel
        FUNCTION(streamSourceFrameChannel, e: IOException)
            // Log IOException and safely close channels
            UndertowLogger.REQUEST_IO_LOGGER.ioException(e)
            IoUtils.safeClose(streamSourceFrameChannel, channel)
        END FUNCTION,
        // Exception handler for sink frame channel
        FUNCTION(streamSinkFrameChannel, e: IOException)
            // Log IOException and safely close channels
            UndertowLogger.REQUEST_IO_LOGGER.ioException(e)
            IoUtils.safeClose(streamSinkFrameChannel, channel)
        END FUNCTION,
        channel.getBufferPool()
    )
END FUNCTION
```

