code:
protected Map<String, Object> loadInstanceDataFromNodeAttributes(
            final INodeEntry node,
            final Description description
    )
    {
        HashMap<String, Object> config = new HashMap<>();

        for (Property property : description.getProperties()) {

            Map<String, Object> renderingOptions = property.getRenderingOptions();

            if (null == renderingOptions) {
                continue;
            }

            Object o = renderingOptions.get(
                    StringRenderingConstants.INSTANCE_SCOPE_NODE_ATTRIBUTE_KEY
            );

            if (null == o || !(o instanceof String)) {
                continue;
            }

            String attribute = (String) o;

            String s = node.getAttributes().get(attribute);

            if (s == null) {
                continue;
            }

            config.put(property.getName(), s);
        }
        return config;
    }

pseudo_code:
```plaintext
// Function to load instance configuration data from node attributes
FUNCTION loadInstanceDataFromNodeAttributes(node, description) RETURNS Map<String, Object>
    // Initialize configuration map
    DECLARE config AS new HashMap<String, Object>()

    // Iterate over properties in the description
    FOR EACH property IN description.getProperties() DO
        // Get rendering options for the property
        DECLARE renderingOptions AS property.getRenderingOptions()

        // Check if rendering options are null
        IF renderingOptions IS NULL THEN
            CONTINUE // Skip to the next property

        // Retrieve the rendering option key for instance scope node attribute
        DECLARE o AS renderingOptions.get(StringRenderingConstants.INSTANCE_SCOPE_NODE_ATTRIBUTE_KEY)

        // Check if the retrieved option is null or not a String
        IF o IS NULL OR NOT (o IS instance of String) THEN
            CONTINUE // Skip to the next property

        // Cast the option to String to get the attribute name
        DECLARE attribute AS (String) o

        // Get the attribute value from the node
        DECLARE s AS node.getAttributes().get(attribute)

        // Check if the attribute value is null
        IF s IS NULL THEN
            CONTINUE // Skip to the next property

        // Put the attribute value into the configuration map with the property name as the key
        config.put(property.getName(), s)
    END FOR

    // Return the populated configuration map
    RETURN config
END FUNCTION
```

