// Function to retrieve a BeanProperty for a given base object and property name
FUNCTION toBeanProperty(base, property) 
    // Retrieve BeanProperties associated with the class of the base object from the cache
    beanProperties = cache.get(base.class)

    // Check if the BeanProperties were not found in the cache
    IF beanProperties IS NULL THEN
        // Create new BeanProperties for the base object's class
        newBeanProperties = BeanProperties(base.class)

        // Attempt to put the new BeanProperties into the cache
        beanProperties = cache.putIfAbsent(base.class, newBeanProperties)

        // Check if the put operation succeeded
        IF beanProperties IS NULL THEN 
            // Use the newly created BeanProperties
            beanProperties = newBeanProperties
        END IF
    END IF

    // Retrieve the BeanProperty for the specified property name, coerced to a string
    beanProperty = property IS NULL ? NULL : beanProperties.getBeanProperty(property.toString())

    // Check if the BeanProperty was not found
    IF beanProperty IS NULL THEN
        // Throw an exception if the property cannot be found
        THROW PropertyNotFoundException("Could not find property " + property + " in " + base.class)
    END IF

    // Return the found BeanProperty
    RETURN beanProperty
END FUNCTION
