// Function to finalize the server bootstrap pipeline configuration
FUNCTION finalizeHandler(ServerBootstrap bootstrap, ChannelOperations.OnSetup operationsFactory, ConnectionObserver connectionObserver)
    // Ensure that the bootstrap, operations factory, and connection observer are not null
    REQUIRE_NOT_NULL(bootstrap, "bootstrap")
    REQUIRE_NOT_NULL(operationsFactory, "operations")
    REQUIRE_NOT_NULL(connectionObserver, "childListener")

    // Declare variable for pipeline handler
    DECLARE pipelineHandler AS BootstrapPipelineHandler
    // Get the current child handler from the bootstrap configuration
    DECLARE currentHandler AS ChannelHandler
    currentHandler = bootstrap.config().childHandler()

    // Check if the current handler is an instance of BootstrapPipelineHandler
    IF currentHandler IS INSTANCE OF BootstrapPipelineHandler THEN
        pipelineHandler = CAST currentHandler TO BootstrapPipelineHandler
    END IF

    // Set a new child handler with the BootstrapInitializerHandler
    bootstrap.childHandler(NEW BootstrapInitializerHandler(pipelineHandler, operationsFactory, connectionObserver))
END FUNCTION
```

