// Function to retrieve the current released version number from the GitHub documentation site
FUNCTION getCurrentReleaseVersion() 
    // Initialize connection variable
    HttpURLConnection connection = null

    // Try block to handle exceptions during the process
    TRY 
        // Get the URL for the version check from settings, with a default URL
        String versionCheckUrl = settings.getString(Settings.KEYS.ENGINE_VERSION_CHECK_URL, "http://jeremylong.github.io/DependencyCheck/current.txt")

        // Create a URL object from the string
        URL url = new URL(versionCheckUrl)

        // Create a connection using a factory
        URLConnectionFactory factory = new URLConnectionFactory(settings)
        connection = factory.createHttpURLConnection(url)

        // Connect to the URL
        connection.connect()

        // Check if the response code is 200 (OK)
        IF connection.getResponseCode() != 200 THEN 
            RETURN null // Return null if the response is not OK

        // Read the release version from the input stream
        String releaseVersion = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8)

        // If a release version was retrieved, return it after trimming whitespace
        IF releaseVersion IS NOT null THEN 
            RETURN releaseVersion.trim()

    CATCH MalformedURLException 
        // Log debug message for malformed URL exception
        LOGGER.debug("Unable to retrieve current release version of dependency-check - malformed url?")

    CATCH URLConnectionFailureException 
        // Log debug message for connection failure exception
        LOGGER.debug("Unable to retrieve current release version of dependency-check - connection failed")

    CATCH IOException 
        // Log debug message for I/O exception
        LOGGER.debug("Unable to retrieve current release version of dependency-check - i/o exception")

    FINALLY 
        // Disconnect the connection if it was established
        IF connection IS NOT null THEN 
            connection.disconnect()

    RETURN null // Return null if no version was retrieved
