// Function to percolate an element up in a maximum heap
FUNCTION percolateUpMaxHeap(index: Integer)

// Initialize hole to the provided index
    INTEGER hole = index

// Store the element at the current hole position
    Activation element = elements[hole]

// While the hole is not at the root and the current element is greater than its parent
    WHILE hole > 1 AND compare(element, elements[hole / 2]) > 0 DO

        // Save the element that is being pushed down
        INTEGER next = hole / 2

        // Move the parent element down to the current hole position
        setElement(hole, elements[next])

        // Update hole to the parent position
        hole = next
    END WHILE

// Place the original element into its new position
    setElement(hole, element)

// End of function
RETURN
```

