// Pseudo-code to return a transport to the pool

FUNCTION returnTransport(returning: Transport) -> VOID
    // Get the current time in milliseconds
    currentTimeMillis: LONG = getCurrentTimeMillis()

    // Declare variable for unwrapped transport
    unwrapped: PooledTransport

    // Check if the returning transport is a leased transport
    IF returning is an instance of LeasedTransport THEN
        // Cast to LeasedTransport and get the delegate
        leasedTransport: LeasedTransport = CAST returning TO LeasedTransport
        unwrapped = leasedTransport.delegate
    ELSE IF returning is an instance of PooledTransport THEN
        // Cast to PooledTransport
        unwrapped = CAST returning TO PooledTransport
    ELSE
        // Throw exception if the transport is not poolable
        THROW EsHadoopIllegalStateException("Cannot return a non-poolable Transport to the pool")
    END IF

    // Check if the unwrapped transport is in the leased map
    IF leased containsKey(unwrapped) THEN
        // Remove from leased and add to idle with current time
        leased.remove(unwrapped)
        idle.put(unwrapped, currentTimeMillis)
    ELSE
        // Throw exception if the transport was not sourced from the pool
        THROW EsHadoopIllegalStateException("Cannot return a Transport object to a pool that was not sourced from the pool")
    END IF
END FUNCTION
