// Function to interpolate the function at a given point
FUNCTION interpolate(inputVector: array of double) RETURNS double

    // Check if the input vector size is valid
    IF (size of inputVector) != (size of this.x[0]) THEN
        // Raise an exception for invalid input size
        THROW IllegalArgumentException("Invalid input vector size: " + (size of inputVector) + ", expected: " + (size of this.x[0]))
    ENDIF

    // Initialize weight and sum variables
    DECLARE weight AS double = 0.0
    DECLARE sum AS double = 0.0

    // Loop through each point in this.x
    FOR i FROM 0 TO (size of this.x) - 1 DO
        // Calculate the distance from inputVector to this.x[i]
        DECLARE r AS double = Math.distance(inputVector, this.x[i])

        // Check if the distance is zero
        IF r == 0.0 THEN
            // Return the corresponding y value if the input matches an existing point
            RETURN y[i]
        ENDIF

        // Calculate weight based on distance
        DECLARE w AS double = Math.pow(r, p)

        // Accumulate weight and weighted sum
        weight += w
        sum += w * y[i]
    ENDFOR

    // Return the interpolated value
    RETURN sum / weight
END FUNCTION
