// FUNCTION to process class with bytecode
FUNCTION processClassWithByteCode(clazz: Class, stream: InputStream, includeFinalMethods: Boolean) 
    // Create a ClassReader instance from the InputStream
    DECLARE reader AS ClassReader = new ClassReader(stream)

    // Create a ClassFieldVisitor instance for visiting fields
    DECLARE visitor AS ClassFieldVisitor = new ClassFieldVisitor(clazz, includeFinalMethods, this)

    // Accept the visitor to read class fields
    reader.accept(visitor, 0)

    // IF the class has a superclass
    IF clazz.getSuperclass() IS NOT NULL THEN
        // Get the resource path of the superclass
        DECLARE name AS String = getResourcePath(clazz.getSuperclass())

        // Get the InputStream of the superclass resource
        DECLARE parentStream AS InputStream = clazz.getResourceAsStream(name)

        // IF the parent stream is available
        IF parentStream IS NOT NULL THEN
            TRY
                // Recursively process the superclass with bytecode
                processClassWithByteCode(clazz.getSuperclass(), parentStream, includeFinalMethods)
            FINALLY
                // Close the parent stream
                parentStream.close()
        ELSE
            // Process the superclass without bytecode
            processClassWithoutByteCode(clazz.getSuperclass(), includeFinalMethods)
        END IF
    END IF

    // IF the class is an interface
    IF clazz.isInterface() THEN
        // Get all interfaces implemented by the class
        DECLARE interfaces AS Class[] = clazz.getInterfaces()

        // FOR each interface in the interfaces array
        FOR each anInterface IN interfaces DO
            // Get the resource path of the interface
            DECLARE name AS String = getResourcePath(anInterface)

            // Get the InputStream of the interface resource
            DECLARE parentStream AS InputStream = clazz.getResourceAsStream(name)

            // IF the parent stream is available
            IF parentStream IS NOT NULL THEN
                TRY
                    // Recursively process the interface with bytecode
                    processClassWithByteCode(anInterface, parentStream, includeFinalMethods)
                FINALLY
                    // Close the parent stream
                    parentStream.close()
            ELSE
                // Process the interface without bytecode
                processClassWithoutByteCode(anInterface, includeFinalMethods)
            END IF
        END FOR
    END IF
END FUNCTION
```

