// Function to calculate the nullity of a singular value decomposition
FUNCTION nullity() RETURNS Integer

    // Check if the singular value decomposition is full
    IF NOT full THEN
        // Throw an exception if not full
        THROW Exception("This is not a FULL singular value decomposition.")
    END IF

    // Initialize the count of negligible singular values
    SET r TO 0

    // Loop through each singular value
    FOR i FROM 0 TO LENGTH(s) - 1 DO
        // Check if the singular value is less than or equal to the tolerance
        IF s[i] <= tol THEN
            // Increment the count of negligible singular values
            INCREMENT r
        END IF
    END FOR

    // Return the count of negligible singular values
    RETURN r
END FUNCTION
