// Function to wait for a Global Secondary Index (GSI) to become active
FUNCTION waitForActive() RETURNS TableDescription

    // Get the table associated with the index
    Table table = getTable()

    // Retrieve the name of the table
    String tableName = table.getTableName()

    // Retrieve the name of the index
    String indexName = getIndexName()

    // Infinite loop to poll the index status
    retry: FOR EVER DO

        // Wait for the table to become active and get its description
        TableDescription desc = table.waitForActive()

        // Get the list of Global Secondary Indexes (GSI) from the table description
        List<GlobalSecondaryIndexDescription> list = desc.getGlobalSecondaryIndexes()

        // IF the list of indexes is not null
        IF list IS NOT NULL THEN

            // Iterate through each Global Secondary Index description
            FOR EACH GlobalSecondaryIndexDescription d IN list DO

                // IF the index name matches the desired index
                IF d.getIndexName().equals(indexName) THEN

                    // Get the current status of the index
                    String status = d.getIndexStatus()

                    // Determine the status of the index
                    SWITCH IndexStatus.fromValue(status) DO
                        CASE ACTIVE:
                            // Return the table description as the index is active
                            RETURN desc

                        CASE CREATING:
                        CASE UPDATING:
                            // Sleep for a defined period before polling again
                            Thread.sleep(SLEEP_TIME_MILLIS)
                            CONTINUE retry

                        DEFAULT:
                            // Throw an exception if the index is not being created or updated
                            THROW IllegalArgumentException("Global Secondary Index " + indexName + " is not being created or updated (with status=" + status + ")")
                    END SWITCH
                END IF
            END FOR
        END IF

        // Throw an exception if the index does not exist in the table
        THROW IllegalArgumentException("Global Secondary Index " + indexName + " does not exist in Table " + tableName + ")")

END FUNCTION
