// Function to get the timeout in nanoseconds for a given RedisCommand
FUNCTION getTimeoutNs(command: RedisCommand) RETURNS long

    // Initialize timeout in nanoseconds
    timeoutNs = -1

    // Retrieve the current state
    state = this.state

    // Check if state is null, if so, initialize it
    IF state IS NULL THEN
        state = this.state = new State(timeoutOptionsSupplier.get())
    END IF

    // Check if default timeout should be applied
    IF NOT state.applyDefaultTimeout THEN
        // Convert timeout from the source to nanoseconds
        timeoutNs = state.timeoutSource.getTimeUnit().toNanos(state.timeoutSource.getTimeout(command))
    END IF

    // Return the timeout if it's greater than 0, otherwise return the default timeout
    RETURN timeoutNs > 0 ? timeoutNs : defaultTimeoutSupplier.getAsLong()

END FUNCTION
