@Override
    public MigratablePipeline findPipelineToMigrate(LoadImbalance imbalance) {
        Set<? extends MigratablePipeline> candidates = imbalance.getPipelinesOwnedBy(imbalance.srcOwner);
        long migrationThreshold = (long) ((imbalance.maximumLoad - imbalance.minimumLoad)
                * MAXIMUM_NO_OF_EVENTS_AFTER_MIGRATION_COEFFICIENT);
        MigratablePipeline candidate = null;
        long loadInSelectedPipeline = 0;
        for (MigratablePipeline pipeline : candidates) {
            long load = imbalance.getLoad(pipeline);
            if (load > loadInSelectedPipeline) {
                if (load < migrationThreshold) {
                    loadInSelectedPipeline = load;
                    candidate = pipeline;
                }
            }
        }
        return candidate;
    }

pseudo_code:
```
// Function to find a pipeline to migrate based on load imbalance
FUNCTION findPipelineToMigrate(LoadImbalance imbalance) RETURNS MigratablePipeline

    // Get the set of candidate pipelines owned by the source owner in the imbalance
    SET candidates = imbalance.getPipelinesOwnedBy(imbalance.srcOwner)

    // Calculate the migration threshold based on maximum and minimum load
    LONG migrationThreshold = (LONG)((imbalance.maximumLoad - imbalance.minimumLoad) * MAXIMUM_NO_OF_EVENTS_AFTER_MIGRATION_COEFFICIENT)

    // Initialize candidate pipeline and load in selected pipeline
    MigratablePipeline candidate = null
    LONG loadInSelectedPipeline = 0

    // Iterate through each candidate pipeline
    FOR EACH pipeline IN candidates DO

        // Get the load of the current pipeline
        LONG load = imbalance.getLoad(pipeline)

        // Check if the load is greater than the load in selected pipeline
        IF load > loadInSelectedPipeline THEN

            // Check if the load is less than the migration threshold
            IF load < migrationThreshold THEN

                // Update the load in selected pipeline and the candidate pipeline
                loadInSelectedPipeline = load
                candidate = pipeline
            END IF
        END IF
    END FOR

    // Return the selected candidate pipeline or null if none found
    RETURN candidate
END FUNCTION
```

