// Function to return the subset of all abstract methods in the given set of methods
FUNCTION abstractMethodsIn(methods: ImmutableSet<ExecutableElement>) RETURNS ImmutableSet<ExecutableElement>
    // Initialize a set to track no-argument methods
    SET noArgMethods = new HashSet()
    // Initialize a builder for the abstract methods set
    SET abstracts = ImmutableSet.Builder<ExecutableElement>()

    // Iterate over each method in the provided set of methods
    FOR EACH method IN methods DO
        // Check if the method is abstract
        IF method.getModifiers().contains(Modifier.ABSTRACT) THEN
            // Check if the method has parameters
            SET hasArgs = NOT method.getParameters().isEmpty()
            // If the method has arguments or is a new no-arg method, add it to the abstract methods
            IF hasArgs OR noArgMethods.add(method.getSimpleName()) THEN
                // Add the method to the abstract methods set
                abstracts.add(method)
            END IF
        END IF
    END FOR

    // Return the built set of abstract methods
    RETURN abstracts.build()
END FUNCTION
