// Function to get the scan end time in seconds
FUNCTION getScanEndTimeSeconds() RETURNS long
    // Initialize the end time with the result from getEndTime
    long end = getEndTime()

    // Check if end time is in milliseconds
    IF (end & Const.SECOND_MASK) != 0L THEN
        // Convert end time to seconds
        end = end / 1000L

        // Handle edge case for ms time between 0 and 1 seconds
        IF (end - (end * 1000) < 1) THEN
            end++ // Increase end by 1 second

    // Check if rollup query is present
    IF rollup_query != null THEN
        // Calculate rollup base time
        RETURN RollupUtils.getRollupBasetime(end + 
            (rollup_query.getRollupInterval().getIntervalSeconds() * 
                rollup_query.getRollupInterval().getIntervals()), 
            rollup_query.getRollupInterval())

    // Check if downsampling is enabled
    IF downsampler != null AND downsampler.getInterval() > 0 THEN
        // Calculate interval offset
        long interval_offset = (1000L * end) % downsampler.getInterval()

        // Align end timestamp to the next representative value
        long interval_aligned_ts = end + (downsampler.getInterval() - interval_offset) / 1000L

        // Check if aligned to timespan boundary
        long timespan_offset = interval_aligned_ts % Const.MAX_TIMESPAN
        IF (0L == timespan_offset) THEN
            RETURN interval_aligned_ts // Already aligned
        ELSE
            RETURN interval_aligned_ts + (Const.MAX_TIMESPAN - timespan_offset) // Align to next timespan

    ELSE
        // Not downsampling, align to the beginning of the next timespan
        long timespan_offset = end % Const.MAX_TIMESPAN
        RETURN end + (Const.MAX_TIMESPAN - timespan_offset) // Align to next timespan
END FUNCTION
