FUNCTION beanMap(property AS String, collection AS Collection) RETURNS Collection
    // Call internal method with iterator of the collection
    RETURN beanMap(property, collection.iterator(), false)
END FUNCTION

FUNCTION beanMap(property AS String, iterator AS Iterator, ignoreErrors AS Boolean) RETURNS Collection
    // Initialize a new collection to hold mapped results
    DECLARE resultCollection AS Collection

    // WHILE there are more elements in the iterator
    WHILE iterator.hasNext()
        // Get the next object from the iterator
        DECLARE currentObject AS Object
        currentObject = iterator.next()

        // TRY to invoke the property method on the current object
        TRY
            // Get the value of the property from the current object
            DECLARE propertyValue AS Object
            propertyValue = currentObject.getProperty(property) // Assuming a method to get the property

            // Add the property value to the result collection
            resultCollection.add(propertyValue)
        EXCEPTION ClassCastException
            // Handle ClassCastException if it occurs
            IF NOT ignoreErrors THEN
                // Rethrow the exception or handle it as needed
                THROW ClassCastException("Error invoking method on object.")
            END IF
        END TRY
    END WHILE

    // RETURN the final collection of property values
    RETURN resultCollection
END FUNCTION
