// Pseudo-code for inheriting owner and group from ancestor if both are empty

FUNCTION inheritOwnerAndGroupIfEmpty(newInode, ancestorInode)
    // Check if inheritance of owner and group is enabled in server configuration
    IF ServerConfiguration.getBoolean(PropertyKey.MASTER_METASTORE_INODE_INHERIT_OWNER_AND_GROUP) THEN
        // Check if new inode's owner is empty
        IF newInode.getOwner().isEmpty() THEN
            // Check if new inode's group is empty
            IF newInode.getGroup().isEmpty() THEN
                // Inherit owner from ancestor inode
                newInode.setOwner(ancestorInode.getOwner())
                // Inherit group from ancestor inode
                newInode.setGroup(ancestorInode.getGroup())
            ENDIF
        ENDIF
    ENDIF
END FUNCTION
