// Function to build a Drawer for a Fragment
FUNCTION buildForFragment() RETURNS Drawer

    // Check if the DrawerBuilder has already been used
    IF mUsed THEN
        THROW RuntimeException("you must not reuse a DrawerBuilder builder")
    END IF

    // Ensure an activity is provided
    IF mActivity IS NULL THEN
        THROW RuntimeException("please pass an activity")
    END IF

    // Ensure a root view is provided
    IF mRootView IS NULL THEN
        THROW RuntimeException("please pass the view which should host the DrawerLayout")
    END IF

    // Mark this builder as used
    mUsed = TRUE

    // Use default DrawerLayout if not set
    IF mDrawerLayout IS NULL THEN
        withDrawerLayout(-1)
    END IF

    // Get the original content view from the root view
    View originalContentView = mRootView.getChildAt(0)

    // Check if the content view is already inflated
    boolean alreadyInflated = (originalContentView.getId() == R.id.materialize_root)

    // Add new layout only if it wasn't inflated before
    IF NOT alreadyInflated THEN
        // Remove the original content view
        mRootView.removeView(originalContentView)
    ELSE
        // If already inflated, clean up all views
        mRootView.removeAllViews()
    END IF

    // Create layout parameters for the content view
    FrameLayout.LayoutParams layoutParamsContentView = new FrameLayout.LayoutParams(
        ViewGroup.LayoutParams.MATCH_PARENT,
        ViewGroup.LayoutParams.MATCH_PARENT
    )

    // Add the drawer layout to the root view
    mRootView.addView(mDrawerLayout, layoutParamsContentView)

    // Set the ID for the drawer layout to check if it was already inflated
    mDrawerLayout.setId(R.id.materialize_root)

    // Handle navigation for ActionBarDrawerToggle and the drawer
    handleDrawerNavigation(mActivity, FALSE)

    // Build the view to be set to the drawer
    Drawer result = buildView()

    // Add the original content view back to the drawer
    mDrawerLayout.addView(originalContentView, 0)

    // Define ID for the slider layout
    mSliderLayout.setId(R.id.material_drawer_slider_layout)

    // Add the slider layout to the drawer
    mDrawerLayout.addView(mSliderLayout, 1)

    // Return the built drawer
    RETURN result
END FUNCTION
```

