// Define the function to create a Key from a URL safe encoded string
FUNCTION fromUrlSafe(urlSafe: String) RETURNS Key
    // Attempt to decode the URL safe string
    TRY
        // Decode the URL safe string using UTF-8 encoding
        utf8Str = URLDecoder.decode(urlSafe, UTF_8.name())

        // Create a new Key builder instance
        keyBuilder = com.google.datastore.v1.Key.newBuilder()

        // Merge the decoded string into the Key builder
        TextFormat.merge(utf8Str, keyBuilder)

        // Build the Key from the builder and return it
        RETURN fromPb(keyBuilder.build())

    // Catch exceptions for unsupported encoding
    CATCH UnsupportedEncodingException AS e
        // Throw an IllegalStateException for unexpected decoding issues
        THROW IllegalStateException("Unexpected decoding exception", e)

    // Catch exceptions for parsing errors
    CATCH TextFormat.ParseException AS e
        // Throw an IllegalArgumentException if key parsing fails
        THROW IllegalArgumentException("Could not parse key", e)
