public HttpServerExchange setStatusCode(final int statusCode) {
        if (statusCode < 0 || statusCode > 999) {
            throw new IllegalArgumentException("Invalid response code");
        }
        int oldVal = state;
        if (allAreSet(oldVal, FLAG_RESPONSE_SENT)) {
            throw UndertowMessages.MESSAGES.responseAlreadyStarted();
        }
        if(statusCode >= 500) {
            if(UndertowLogger.ERROR_RESPONSE.isDebugEnabled()) {
                UndertowLogger.ERROR_RESPONSE.debugf(new RuntimeException(), "Setting error code %s for exchange %s", statusCode, this);
            }
        }
        this.state = oldVal & ~MASK_RESPONSE_CODE | statusCode & MASK_RESPONSE_CODE;
        return this;
    }

pseudo_code:
```
// Function to set the status code for a response
FUNCTION setStatusCode(statusCode: INTEGER) RETURNS HttpServerExchange

    // Check if the provided status code is within valid range
    IF statusCode < 0 OR statusCode > 999 THEN
        // Throw an exception for invalid response code
        THROW IllegalArgumentException("Invalid response code")
    END IF

    // Store the current state
    INTEGER oldVal = state

    // Check if the response has already been sent
    IF allAreSet(oldVal, FLAG_RESPONSE_SENT) THEN
        // Throw an exception indicating the response has already started
        THROW UndertowMessages.MESSAGES.responseAlreadyStarted()
    END IF

    // Check if status code indicates an error
    IF statusCode >= 500 THEN
        // Log the error code setting for debugging purposes
        IF UndertowLogger.ERROR_RESPONSE.isDebugEnabled() THEN
            UndertowLogger.ERROR_RESPONSE.debugf(new RuntimeException(), "Setting error code %s for exchange %s", statusCode, this)
        END IF
    END IF

    // Update the state with the new status code
    this.state = oldVal AND NOT MASK_RESPONSE_CODE OR statusCode AND MASK_RESPONSE_CODE

    // Return the current instance
    RETURN this
END FUNCTION
```

