        // Return a failed data source due to prefetch being disabled
        RETURN DataSources.immediateFailedDataSource(PREFETCH_EXCEPTION)
    END IF

    TRY
        // Get the producer sequence for the encoded image prefetch
        producerSequence = mProducerSequenceFactory.getEncodedImagePrefetchProducerSequence(imageRequest)

        // Submit the prefetch request and return the data source
        RETURN submitPrefetchRequest(producerSequence, imageRequest, ImageRequest.RequestLevel.FULL_FETCH, callerContext, priority)

