public static String getterIntoProperty(String getterName) {
        if (getterName == null) {
            return getterName;
        }
        int length = getterName.length();
        if (!getterName.startsWith(GETTER_PREFIX) || length <= GETTER_PREFIX.length()) {
            return getterName;
        }

        String propertyName = getterName.substring(GETTER_PREFIX.length(), length);
        char firstChar = propertyName.charAt(0);
        if (isLetter(firstChar)) {
            if (isLowerCase(firstChar)) {
                //ok, apparently this is not a JavaBean getter, better leave it untouched
                return getterName;
            }
            propertyName = toLowerCase(firstChar) + propertyName.substring(1, propertyName.length());
        }
        return propertyName;
    }

pseudo_code:
```
// Function to convert a getter method name into a property name
FUNCTION getterIntoProperty(getterName: String) RETURNS String
    // Check if the input is null
    IF getterName IS NULL THEN
        RETURN getterName

    // Get the length of the getter name
    SET length TO LENGTH(getterName)

    // Check if it starts with 'get-' prefix or if it is too short
    IF NOT getterName.STARTS_WITH("get-") OR length <= LENGTH("get-") THEN
        RETURN getterName

    // Extract the property name by removing the 'get-' prefix
    SET propertyName TO SUBSTRING(getterName, LENGTH("get-"), length)

    // Get the first character of the property name
    SET firstChar TO CHAR_AT(propertyName, 0)

    // Check if the first character is a letter
    IF isLetter(firstChar) THEN
        // Check if the first character is lower case
        IF isLowerCase(firstChar) THEN
            // Not a valid JavaBean getter, return original getter name
            RETURN getterName
        END IF

        // Convert the first character to lower case and reconstruct property name
        SET propertyName TO toLowerCase(firstChar) + SUBSTRING(propertyName, 1, LENGTH(propertyName))

    END IF

    // Return the converted property name
    RETURN propertyName
END FUNCTION
```

