// Function to flatten (key1, key2, value) triples
FUNCTION flattenEntries(fn: TriFunction<K1, K2, V, R>) 
    // Initialize output as a set of result type R
    DECLARE resultSet AS Set<R>

    // Iterate over each outer entry in the entry set
    FOR EACH outer IN entrySet() DO
        // Iterate over each inner entry in the outer value's entry set
        FOR EACH inner IN outer.getValue().entrySet() DO
            // Apply the function fn to create an entry from the keys and value
            DECLARE entry AS fn.apply(outer.getKey(), inner.getKey(), inner.getValue())
            // Add the created entry to the result set
            ADD entry TO resultSet
        END FOR
    END FOR

    // Return the set of entries
    RETURN resultSet
END FUNCTION
