// Pseudo-code for initializing the initial state of a TaintFrame

FUNCTION initEntryFact(fact: TaintFrame) // Input: TaintFrame fact
    // Set the TaintFrame as valid
    fact.setValid()

    // Clear the stack of the TaintFrame
    fact.clearStack()

    // Check if currently in the main method
    boolean inMainMethod = isInMainMethod()

    // Get the number of slots and local variables from the TaintFrame
    int numSlots = fact.getNumSlots()
    int numLocals = fact.getNumLocals()

    // Iterate through each slot in the TaintFrame
    FOR i FROM 0 TO numSlots - 1 DO
        // Initialize Taint value as UNKNOWN
        Taint value = new Taint(Taint.State.UNKNOWN)

        // Check if the index is within the number of local variables
        IF i < numLocals THEN
            // Check if the index corresponds to a parameter
            IF i < parameterStackSize THEN
                int stackOffset = parameterStackSize - i - 1

                // Check if the parameter is tainted by annotation
                IF isTaintedByAnnotation(i - 1) THEN
                    value = new Taint(Taint.State.TAINTED)
                    // Optionally add line number for the first instruction in the method
                    // value.addLocation(new TaintLocation(methodDescriptor, 0, ""), true)

                // Check if in the main method
                ELSE IF inMainMethod THEN
                    // Check global configuration for tainted main argument
                    IF FindSecBugsGlobalConfig.getInstance().isTaintedMainArgument() THEN
                        value = new Taint(Taint.State.TAINTED)
                    ELSE
                        value = new Taint(Taint.State.SAFE)
                    END IF
                ELSE
                    // Add parameter index to the Taint value
                    value.addParameter(stackOffset)
                END IF

                // Set the source of the Taint value
                value.addSource(new UnknownSource(UnknownSourceType.PARAMETER, value.getState()).setParameterIndex(stackOffset))
            END IF

            // Set the variable index for the Taint value
            value.setVariableIndex(i)
        END IF

        // Set the value of the TaintFrame at index i
        fact.setValue(i, value)
    END FOR
END FUNCTION
```

