// Function to add exclude patterns to the directory scanner
FUNCTION addExcludes(excludes: Array of String) RETURNS DirectoryScanner

    // Check if the excludes array is not null and has elements
    IF excludes IS NOT NULL AND excludes.length > 0 THEN

        // Check if the current exclude patterns are not null and have elements
        IF this.excludes IS NOT NULL AND this.excludes.length > 0 THEN

            // Create a temporary array to hold combined exclude patterns
            DECLARE tmp AS Array of String WITH SIZE excludes.length + this.excludes.length

            // Copy current exclude patterns to temporary array
            System.arraycopy(this.excludes, 0, tmp, 0, this.excludes.length)

            // Normalize and add new exclude patterns to the temporary array
            FOR i FROM 0 TO excludes.length - 1 DO
                tmp[this.excludes.length + i] = normalizePattern(excludes[i])
            END FOR

            // Update the current exclude patterns with the combined array
            this.excludes = tmp

        ELSE
            // If there are no current exclude patterns, set the new ones
            setExcludes(excludes)
        END IF

    END IF

    // Return the current instance of DirectoryScanner
    RETURN this
END FUNCTION
