// Function to handle an indexed header
FUNCTION handleIndex(index: Integer)

// Check if the index is within the static table length
IF index <= Hpack.STATIC_TABLE_LENGTH THEN
    // Add entry from static table
    addStaticTableEntry(index)
ELSE
    // Calculate the adjusted index for dynamic header table
    adjustedIndex = getRealIndex(index - Hpack.STATIC_TABLE_LENGTH)

    // Retrieve the header field from the header table
    headerField = headerTable[adjustedIndex]

    // Emit the header with its name and value
    headerEmitter.emitHeader(headerField.name, headerField.value, false)
END IF

// End of function
RETURN
