// Function to wait until a specified DynamoDB table transitions to ACTIVE state
FUNCTION waitUntilActive(dynamo: AmazonDynamoDB, tableName: String) 
    // Throws an exception if interrupted
    THROWS InterruptedException, TableNeverTransitionedToStateException

    // Call the internal function with default timeout and interval
    CALL waitUntilActive(dynamo, tableName, DEFAULT_WAIT_TIMEOUT, DEFAULT_WAIT_INTERVAL)
END FUNCTION

// Internal function to wait until the table is active
FUNCTION waitUntilActive(dynamo: AmazonDynamoDB, tableName: String, waitTimeout: Integer, waitInterval: Integer) 
    // Initialize the elapsed time to zero
    elapsedTime = 0

    // Loop until the elapsed time exceeds the wait timeout
    WHILE elapsedTime < waitTimeout 
        // Get the current status of the table
        tableStatus = GET table status FROM dynamo USING tableName

        // Check if the table status is ACTIVE
        IF tableStatus EQUALS "ACTIVE" THEN
            RETURN // Exit function if the table is active

        // Sleep for the specified wait interval
        CALL sleep(waitInterval)

        // Update the elapsed time
        elapsedTime = elapsedTime + waitInterval
    END WHILE

    // If the loop exits without finding the table active, throw an exception
    THROW TableNeverTransitionedToStateException
END FUNCTION
