FUNCTION readFile(InputStream file) RETURNS String
    // Initialize a BufferedInputStream to read the input stream
    OPEN BufferedInputStream stream FROM file

    // Initialize a buffer to store read bytes
    INITIALIZE byte[] buff WITH size 1024

    // Initialize a StringBuilder to build the output string
    INITIALIZE StringBuilder builder

    // Variable to hold the number of bytes read
    INITIALIZE int read

    // Loop until the end of the stream is reached
    WHILE (read = stream.read(buff)) IS NOT -1 DO
        // Append the read bytes converted to String using UTF-8 encoding to the builder
        builder.append(new String(buff, 0, read, StandardCharsets.UTF_8))
    END WHILE

    // Return the constructed string from the StringBuilder
    RETURN builder.toString()
END FUNCTION
