// Function to get the exact content length from a download connection
FUNCTION getExactContentLengthRangeFrom0(connected : DownloadConnection.Connected) : LONG
    // Initialize contentLength to -1 to indicate unknown length
    contentLength = -1

    // Get the content range header field
    contentRangeField = connected.getResponseHeaderField(CONTENT_RANGE)

    // Check if the content range field is not empty
    IF NOT Util.isEmpty(contentRangeField) THEN
        // Extract the right range value from the content range
        rightRange = getRangeRightFromContentRange(contentRangeField)

        // Calculate content length for range starting from 0
        IF rightRange > 0 THEN
            contentLength = rightRange + 1
        END IF
    END IF

    // If content length is still unknown, check the content length header field
    IF contentLength < 0 THEN
        contentLengthField = connected.getResponseHeaderField(CONTENT_LENGTH)

        // Check if the content length field is not empty
        IF NOT Util.isEmpty(contentLengthField) THEN
            // Parse the content length value
            contentLength = LONG.parseLong(contentLengthField)
        END IF
    END IF

    // Return the determined content length
    RETURN contentLength
END FUNCTION
