public void updateItemAt(int index, T item) {
        final T existing = get(index);
        // assume changed if the same object is given back
        boolean contentsChanged = existing == item || !mCallback.areContentsTheSame(existing, item);
        if (existing != item) {
            // different items, we can use comparison and may avoid lookup
            final int cmp = mCallback.compare(existing, item);
            if (cmp == 0) {
                mData[index] = item;
                if (contentsChanged) {
                    mCallback.onChanged(index, 1);
                }
                return;
            }
        }
        if (contentsChanged) {
            mCallback.onChanged(index, 1);
        }
        // TODO this done in 1 pass to avoid shifting twice.
        removeItemAtIndex(index, false);
        int newIndex = add(item, false);
        if (index != newIndex) {
            mCallback.onMoved(index, newIndex);
        }
    }

pseudo_code:
```
// FUNCTION to update an item at a given index in a sorted list
FUNCTION updateItemAt(index: Integer, item: T)

// Retrieve the existing item at the specified index
    existing ← get(index)

// Check if the contents have changed
    contentsChanged ← existing = item OR NOT mCallback.areContentsTheSame(existing, item)

// IF the existing item is different from the new item
    IF existing ≠ item THEN
        // Compare existing item with the new item
        cmp ← mCallback.compare(existing, item)

        // IF items are considered equal based on comparison
        IF cmp = 0 THEN
            // Update the item at the specified index
            mData[index] ← item

            // IF contents have changed, notify the change
            IF contentsChanged THEN
                mCallback.onChanged(index, 1)
            RETURN
        ENDIF
    ENDIF

    // IF contents have changed, notify the change
    IF contentsChanged THEN
        mCallback.onChanged(index, 1)
    ENDIF

    // Remove the item at the index without shifting
    removeItemAtIndex(index, false)

    // Add the new item and retrieve the new index
    newIndex ← add(item, false)

    // IF the new position is different from the provided index
    IF index ≠ newIndex THEN
        // Notify that the item has moved
        mCallback.onMoved(index, newIndex)
    ENDIF
END FUNCTION
```

