    IF NOT matches(sequence) THEN
        // Throw an exception if the queue does not match the expected sequence
        THROW IllegalStateException("Queue did not match expected sequence")
    END IF

    // Get the length of the sequence
    length = LENGTH(sequence)

    // Check if the queue is long enough to consume the sequence
    IF length > remainingLength() THEN
        // Throw an exception if the queue is not long enough
        THROW IllegalStateException("Queue not long enough to consume sequence")
    END IF

    // Update the position in the queue after consuming the sequence
    pos = pos + length
END FUNCTION
