// Pseudo-code for committing a block in a distributed system

FUNCTION commitBlock(workerId, usedBytesOnTier, tierAlias, blockId, length) 
    // Log the commit operation details
    LOG.debug("Commit block from workerId: {}, usedBytesOnTier: {}, blockId: {}, length: {}", workerId, usedBytesOnTier, blockId, length)

    // Retrieve the worker information based on workerId
    MasterWorkerInfo worker = getWorkerById(workerId) // Function to get worker by ID
    IF worker IS NULL THEN 
        // Handle case where worker is not found
        THROW NotFoundException("No worker found with ID: " + workerId)
    END IF

    // Create a journal context for logging
    try (JournalContext journalContext = createJournalContext()) 
        // Lock the worker metadata
        LOCK worker 
            // Lock the specified block
            try (LockResource lockResource = lockBlock(blockId)) 
                // Retrieve block metadata
                Optional<BlockMeta> block = getBlockMetadata(blockId) // Function to get block metadata
                IF NOT block.isPresent() OR block.get().getLength() != length THEN 
                    // Handle block length change attempt
                    IF block.isPresent() AND block.get().getLength() != Constants.UNKNOWN_SIZE THEN 
                        LOG.warn("Rejecting attempt to change block length from {} to {}", block.get().getLength(), length)
                    ELSE 
                        // Update the block metadata with the new length
                        putBlockMetadata(blockId, BlockMeta.newBuilder().setLength(length).build()) // Function to put block metadata
                        BlockInfoEntry blockInfo = BlockInfoEntry.newBuilder().setBlockId(blockId).setLength(length).build()
                        journalContext.append(JournalEntry.newBuilder().setBlockInfo(blockInfo).build())
                    END IF
                END IF

                // Update the block's location with the worker's information
                addBlockLocation(blockId, BlockLocation.newBuilder().setWorkerId(workerId).setTier(tierAlias).build()) // Function to add block location
                // Remove the block from the list of lost blocks
                removeLostBlock(blockId)

                // Update the worker's information for the new block
                worker.addBlock(blockId)
                worker.updateUsedBytes(tierAlias, usedBytesOnTier)
                worker.updateLastUpdatedTimeMs()
            END TRY
        END LOCK
    END TRY
END FUNCTION
