// Function to choose the best method node for method reference
FUNCTION chooseMethodRefMethodCandidate(methodRef, candidates: List of MethodNode) RETURNS MethodNode

    // Check if there is only one candidate
    IF candidates.size() == 1 THEN
        // Return the single candidate
        RETURN candidates.get(0)
    END IF

    // Create a stream of candidates and calculate matching scores
    bestMethodNode = candidates.stream()
        // Map each candidate to a tuple of candidate and its matching score
        .map(candidate -> Tuple.tuple(candidate, matchingScore(candidate, methodRef)))
        // Find the candidate with the highest matching score
        .min((tuple1, tuple2) -> Integer.compare(tuple2.getV2(), tuple1.getV2()))
        // Extract the method node from the tuple
        .map(tuple -> tuple.getV1())
        // If no method node is found, return null
        .orElse(null)

    // Return the best method node found
    RETURN bestMethodNode
END FUNCTION
```

