FUNCTION getScriptSource(isScriptFile: BOOLEAN, script: STRING) RETURNS GroovyCodeSource
    // Check if the script is a file
    IF isScriptFile THEN
        // Hunt for the script file based on the provided location
        scriptFile = huntForTheScriptFile(script)

        // Check if the file exists
