// Function to concatenate path parts into a single path
FUNCTION getPath(parts: Array of String) RETURNS String
    // Check if parts is null or empty
    IF parts IS NULL OR length of parts = 0 THEN
        // Throw an exception for invalid input
        THROW IllegalArgumentException("Parts is null or empty.")
    ENDIF

    // Initialize a StringBuilder to build the path
    DECLARE builder AS StringBuilder

    // Loop through each part in the parts array
    FOR i FROM 0 TO length of parts - 1 DO
        DECLARE part AS parts[i]
        // Append the current part to the builder
        builder.append(part)

        // Check if there are more parts to add
        DECLARE hasMore AS (i < length of parts - 1)
        // Append the file separator if needed
        IF NOT part.endsWith(File.separator) AND hasMore THEN
            builder.append(File.separator)
        ENDIF
    ENDFOR

    // Return the constructed path as a string
    RETURN builder.toString()
ENDFUNCTION
