code:
@Override
    public final String readUTF() throws IOException {
        int charCount = readInt();
        if (charCount == NULL_ARRAY_LENGTH) {
            return null;
        }
        if (charBuffer == null || charCount > charBuffer.length) {
            charBuffer = new char[charCount];
        }
        byte b;
        for (int i = 0; i < charCount; i++) {
            b = readByte();
            if (b < 0) {
                charBuffer[i] = Bits.readUtf8Char(this, b);
            } else {
                charBuffer[i] = (char) b;
            }
        }
        return new String(charBuffer, 0, charCount);
    }

pseudo_code:
```
// Function to read a UTF-8 encoded string from an input stream
FUNCTION readUTF() RETURNS String
    // Read the number of characters in the UTF-8 string
    int charCount = readInt()

    // Check if the character count indicates a null value
    IF charCount == NULL_ARRAY_LENGTH THEN
        RETURN null

    // Allocate character buffer if necessary
    IF charBuffer is null OR charCount > charBuffer.length THEN
        charBuffer = new char[charCount]

    // Loop through each byte to construct the string
    FOR int i = 0 TO charCount - 1 DO
        // Read a byte from the input stream
        byte b = readByte()

        // Check if the byte is negative
        IF b < 0 THEN
            // Read a UTF-8 character from the byte
            charBuffer[i] = Bits.readUtf8Char(this, b)
        ELSE
            // Convert the byte to a character
            charBuffer[i] = (char) b

    // Return the constructed string
    RETURN new String(charBuffer, 0, charCount)
END FUNCTION
```

