Handles the if-none-match header. returns true if the request should proceed, false otherwise

@param ifNoneMatch the header
@param etags       The etags
@return

code:
public static boolean handleIfNoneMatch(final String ifNoneMatch, final List<ETag> etags, boolean allowWeak) {
        if (ifNoneMatch == null) {
            return true;
        }
        List<ETag> parts = parseETagList(ifNoneMatch);
        for (ETag part : parts) {
            if (part.getTag().equals("*")) {
                return false;
            }
            if (part.isWeak() && !allowWeak) {
                continue;
            }
            for (ETag tag : etags) {
                if (tag != null) {
                    if (tag.isWeak() && !allowWeak) {
                        continue;
                    }
                    if (tag.getTag().equals(part.getTag())) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

pseudo_code:
```
// Function to handle the if-none-match header
FUNCTION handleIfNoneMatch(ifNoneMatch: String, etags: List<ETag>, allowWeak: Boolean) RETURNS Boolean
    // Check if ifNoneMatch header is null
    IF ifNoneMatch IS NULL THEN
        RETURN true // Proceed with the request

    // Parse the ifNoneMatch header into a list of ETags
    parts = parseETagList(ifNoneMatch)

    // Iterate through each ETag part from the ifNoneMatch
    FOR each part IN parts DO
        // Check if the part is a wildcard
        IF part.getTag() EQUALS "*" THEN
            RETURN false // Do not proceed with the request

        // Check if the part is weak and weak tags are not allowed
        IF part.isWeak() AND NOT allowWeak THEN
            CONTINUE // Skip to the next part

        // Iterate through the provided etags
        FOR each tag IN etags DO
            // Check if the tag is not null
            IF tag IS NOT NULL THEN
                // Check if the tag is weak and weak tags are not allowed
                IF tag.isWeak() AND NOT allowWeak THEN
                    CONTINUE // Skip to the next tag

                // Check if the tag matches the current part
                IF tag.getTag() EQUALS part.getTag() THEN
                    RETURN false // Do not proceed with the request

    RETURN true // Proceed with the request
