// Function to rollback the destination replica versions after migration failure
FUNCTION rollbackDestination()
    // Get the partition identifier
    partitionId = getPartitionId()
    // Get the partition service
    partitionService = getService()
    // Get the replica manager from the partition service
    replicaManager = partitionService.getReplicaManager()
    // Get the logger instance
    logger = getLogger()

    // Get the current replica index for the destination
    destinationCurrentReplicaIndex = migrationInfo.getDestinationCurrentReplicaIndex()

    // Check if the destination current replica index is invalid
    IF destinationCurrentReplicaIndex == -1 THEN
        // Clear the partition replica versions in the destination
        clearPartitionReplicaVersions(partitionId)
        // Log the action if logging is enabled
        IF logger.isFinestEnabled() THEN
            logger.finest("Replica versions are cleared in destination after failed migration. partitionId=" + partitionId)
        ENDIF
    ELSE
        // Determine the replica offset based on the current replica index
        replicaOffset = IF migrationInfo.getDestinationCurrentReplicaIndex() <= 1 THEN 1 ELSE migrationInfo.getDestinationCurrentReplicaIndex()

        // Iterate over each service namespace associated with the partition
        FOR namespace IN replicaManager.getNamespaces(partitionId) DO
            // Update the partition replica versions for the current namespace
            versions = updatePartitionReplicaVersions(replicaManager, partitionId, namespace, replicaOffset - 1)

            // Log the rollback action if logging is enabled
            IF logger.isFinestEnabled() THEN
