// Function to restore max-heap condition after a node's priority is increased
FUNCTION siftUp(arr: Array of Comparable, k: Integer)
    // Continue while the current position is not the root and the parent is less than the current node
    WHILE k > 1 AND arr[k/2] < arr[k] DO
        // Swap the current node with its parent
        swap(arr, k, k/2)
        // Move up to the parent's position
        k = k / 2
    END WHILE
END FUNCTION
