Return the (potentially inherited) field of the classnode.

@param classNode the classnode
@param fieldName the name of the field
@return the field or null if not found

code:
public static FieldNode getField(ClassNode classNode, String fieldName) {
        ClassNode node = classNode;
        Set<String> visited = new HashSet<String>();
        while (node != null) {
            FieldNode fn = node.getDeclaredField(fieldName);
            if (fn != null) return fn;
            ClassNode[] interfaces = node.getInterfaces();
            for (ClassNode iNode : interfaces) {
                if (visited.contains(iNode.getName())) continue;
                FieldNode ifn = getField(iNode, fieldName);
                visited.add(iNode.getName());
                if (ifn != null) return ifn;
            }
            node = node.getSuperClass();
        }
        return null;
    }

pseudo_code:
```
// Function to return the (potentially inherited) field of the class node
FUNCTION getField(classNode: ClassNode, fieldName: String) -> FieldNode
    // Initialize the current node to the provided class node
    node = classNode

    // Initialize a set to keep track of visited interfaces
    visited = new Set<String>()

    // Loop until there are no more nodes to process
    WHILE node IS NOT NULL DO
        // Attempt to get the declared field from the current node
        fn = node.getDeclaredField(fieldName)

        // If the field is found, return it
        IF fn IS NOT NULL THEN
            RETURN fn
        ENDIF

        // Retrieve the interfaces implemented by the current node
        interfaces = node.getInterfaces()

        // Loop through each interface
        FOR each iNode IN interfaces DO
            // If the interface has already been visited, skip it
            IF visited.contains(iNode.getName()) THEN
                CONTINUE
            ENDIF

            // Recursively call getField on the interface node
            ifn = getField(iNode, fieldName)

            // Mark the interface as visited
            visited.add(iNode.getName())

            // If the field is found in the interface, return it
            IF ifn IS NOT NULL THEN
                RETURN ifn
            ENDIF
        ENDFOR

        // Move to the superclass of the current node
        node = node.getSuperClass()
    ENDWHILE

    // Return null if the field is not found in the class or its interfaces
    RETURN null
END FUNCTION
```

