// Define a function that creates a predicate for checking suffixes
FUNCTION suffixes(paths: Array of String) RETURNS Predicate
    // Check if there is only one suffix provided
    IF length of paths is equal to 1 THEN
        // Return a predicate that checks the single suffix
        RETURN suffix(paths[0])
    END IF

    // Create an array to hold predicates for each path suffix
    DECLARE predicates as Array of PathSuffixPredicate with size equal to length of paths

    // Loop through each path suffix
    FOR i FROM 0 TO length of paths - 1 DO
        // Initialize a new PathSuffixPredicate for the current suffix
        predicates[i] = new PathSuffixPredicate(paths[i])
    END FOR

    // Combine all predicates using logical OR and return
    RETURN or(predicates)
END FUNCTION
```

