FUNCTION squaredDistance(INTEGER ARRAY x, INTEGER ARRAY y) RETURNS DOUBLE

    // Check if the lengths of the two input vectors are equal
    IF LENGTH(x) != LENGTH(y) THEN
        // Raise an error for different input vector sizes
        THROW IllegalArgumentException("Input vector sizes are different.")
    END IF

    // Initialize the sum of squared differences
    DOUBLE sum = 0.0

    // Iterate through each element of the input vectors
    FOR INTEGER i = 0 TO LENGTH(x) - 1 DO
        // Calculate the squared difference and accumulate to sum
        sum += sqr(x[i] - y[i])
    END FOR

    // Return the total squared distance
    RETURN sum
