// Function to normalize slashes in a given path
FUNCTION normalizeSlashes(path: String) -> String
    // Prepare a mutable string builder with the input path
    DECLARE builder AS StringBuilder(path)
    DECLARE modified AS Boolean = false

    // Remove all trailing slashes except the first one
    WHILE builder.length() > 0 AND builder.length() != 1 AND PATH_SEPARATOR == builder.charAt(builder.length() - 1) DO
        // Remove the last character from the builder
        builder.deleteCharAt(builder.length() - 1)
        modified = true
    END WHILE

    // Add a slash at the beginning if one isn't present
    IF builder.length() == 0 OR PATH_SEPARATOR != builder.charAt(0) THEN
        // Insert the PATH_SEPARATOR at the beginning
        builder.insert(0, PATH_SEPARATOR)
        modified = true
    END IF

    // Only create and return the modified string if it was changed
    IF modified THEN
        RETURN builder.toString()
    END IF

    // Return the original path if no modifications were made
    RETURN path
END FUNCTION
```

