        IF forwardedIpsStr IS NOT NULL AND SIZE(forwardedIpsStr) > 0 THEN
            // Return the first IP address from the list
            RETURN forwardedIpsStr[0]
        END IF
    END IF

    // Return null if the conditions are not met
    RETURN NULL
END FUNCTION
